//! Markup metadata of the types of this crate, declared apart from the
//! types themselves: enumerations, value types and their text forms,
//! contracts, plain classes and collections, and the `markup` part of the
//! classes of the object model.
//!
//! `enums.rs` and `classes.rs` are generated by
//! `scripts/generate_markup_types.py` (hand-written members of classes are in
//! `scripts/markup_types_overrides.py`); the other files are written by hand.
//!
//! Everything here uses only the public interface of the types. A member
//! the managed original has and that is missing here is either not ported
//! or cannot be expressed with the current interface of its type.

use crate::assigned_binding::AssignedBinding;
use ferroui_base::data::core::ValueTypes;
use ferroui_base::metadata::MarkupType;

mod classes;
mod contracts;
mod converters;
mod enums;
pub(crate) mod lists;
mod plain;
mod values;

// The carriers of the metadata of instantiations of types of the base crate: public
// (hidden) so that generated Rust source can call the typed functions of their members.
pub use contracts::AddChildOf;
pub use plain::FerroListOf;

#[cfg(test)]
mod markup_types_tests;

/// The lists of the types declared in this module, by area.
pub(crate) const TYPE_LISTS: &[&[&MarkupType]] =
    &[enums::TYPES, values::TYPES, contracts::TYPES, plain::TYPES, classes::TYPES, converters::TYPES, crate::documents::MARKUP_TYPES, crate::context_menu_event_args::MARKUP_TYPES, crate::rich_text::MARKUP_TYPES, crate::rich_edit_box::MARKUP_TYPES];

/// Adds the types declared in this module to the process-wide table of
/// types with markup metadata. Called once by `register_types()`.
pub(crate) fn register() {
    for types in TYPE_LISTS {
        MarkupType::register_all(types);
    }
    // The navigation model of WinUI's Frame, declared next to its types (namespace
    // FerroUI.Navigation, docs/porting/winui-controls.md, section 7).
    MarkupType::register_all(crate::navigation::MARKUP_TYPES);
    // The enumerations and the event arguments of WinUI's NavigationView, declared next to them.
    MarkupType::register_all(crate::navigation_view_events::MARKUP_TYPES);
    // A binding a property holds as its value is a binding: the wrapper is one more handle of
    // the binding type, so that a property of that type is a property of binding type.
    let binding = <dyn ferroui_base::data::BindingBase as ferroui_base::metadata::MarkupTyped>::MARKUP;
    MarkupType::register_handle::<AssignedBinding>(binding);
    MarkupType::register_handle::<Option<AssignedBinding>>(binding);
    ValueTypes::register_global(register_value_types);
    lists::PipsList::register();
}

/// Registers what the untyped value conversions need to know about the
/// types declared in this module (nullable forms, reference types). The
/// conversions are per thread: this runs on every thread, when the thread
/// next converts an untyped value ([`ValueTypes::register_global`]).
fn register_value_types() {
    enums::register_value_types();
    values::register_value_types();
    contracts::register_value_types();
    plain::register_value_types();
    classes::register_value_types();
    converters::register_value_types();
    crate::documents::register_value_types();
    crate::context_menu_event_args::register_value_types();
    crate::rich_text::register_value_types();
    crate::rich_edit_box::register_value_types();
    register_assigned_binding();
    // The delegate of `DataValidationErrors.ErrorConverter` (`Func<object, object>?`): a binding
    // delivers a converter, and the property holds the nullable form.
    ValueTypes::register_nullable::<crate::ErrorConverter>();
}

/// The casts between a binding and the value of a property that is assigned a binding.
fn register_assigned_binding() {
    use ferroui_base::data::{BindingBase, CompiledBinding, MultiBinding, ReflectionBinding, TemplateBinding};
    use std::rc::Rc;

    ValueTypes::register_nullable::<AssignedBinding>();
    ValueTypes::register_cast::<Rc<dyn BindingBase>, AssignedBinding>(|binding| AssignedBinding::new(binding.clone()));
    ValueTypes::register_cast::<Rc<CompiledBinding>, AssignedBinding>(|binding| AssignedBinding::new(binding.clone()));
    ValueTypes::register_cast::<Rc<ReflectionBinding>, AssignedBinding>(|binding| AssignedBinding::new(binding.clone()));
    ValueTypes::register_cast::<Rc<MultiBinding>, AssignedBinding>(|binding| AssignedBinding::new(binding.clone()));
    ValueTypes::register_cast::<Rc<TemplateBinding>, AssignedBinding>(|binding| AssignedBinding::new(binding.clone()));
    ValueTypes::register_cast::<AssignedBinding, Rc<dyn BindingBase>>(|binding| binding.0.clone());
}
